window.COURSE=[{"id": "rational", "group": "Алгебра", "title": "Рациональные числа и знаки", "idea": "Числовая прямая похожа на этажи: выше нуля — положительные числа, ниже — отрицательные. Рациональное число можно записать дробью m/n, где m — целое, а n — натуральное.", "steps": ["На прямой больше то число, которое правее. Поэтому −2 > −5. Модуль — расстояние до нуля: |−5| = 5.", "Складывая числа разных знаков, вычти меньший модуль из большего и возьми знак числа с большим модулем. Вычесть число — значит прибавить противоположное.", "При умножении и делении одинаковые знаки дают плюс, разные — минус. Нулём делить нельзя."], "example": ["−7 + 10 − 5", "−7 + 10 = 3: десятка перевесила семёрку.", "3 − 5 = −2. Проверка: на прямой от 3 идём на пять шагов влево."], "error": "Два минуса дают плюс при умножении, но −3 + (−2) = −5. Сначала посмотри на действие.", "lab": "numberline", "qs": [{"q": "−8 + 13 = ?", "a": 5, "why": "13 − 8 = 5."}, {"q": "−4 · (−6) = ?", "a": 24, "why": "Два отрицательных множителя дают положительное произведение."}, {"q": "|−9| = ?", "a": 9, "why": "Модуль — неотрицательное расстояние до нуля."}]}, {"id": "intervals", "group": "Алгебра", "title": "Числовые промежутки и расстояния", "idea": "Промежуток — целый участок числовой прямой. Скобки показывают, включены ли его концы.", "steps": ["[a;b] включает оба конца: a ≤ x ≤ b. (a;b) не включает их: a < x < b. Возможны смешанные скобки.", "Луч x ≥ a записывают [a;+∞). Бесконечность — не число и не включённый конец; рядом с ней всегда круглая скобка.", "Расстояние между точками с координатами a и b равно |a−b|. Оно не бывает отрицательным."], "example": ["Какие целые числа входят в (−2;3]?", "−2 не входит, 3 входит.", "Числа: −1, 0, 1, 2, 3. Всего пять."], "error": "Круглая скобка исключает конец, квадратная включает. Не пропускай отрицательные числа.", "lab": "intervals", "qs": [{"q": "Расстояние между −3 и 5?", "a": 8, "why": "|5−(−3)|=8."}, {"q": "Сколько целых чисел в [1;4]?", "a": 4, "why": "1,2,3,4."}, {"q": "Наименьшее целое число в (−2;3]?", "a": -1, "why": "−2 исключено; следующее целое −1."}]}, {"id": "fractions", "group": "Алгебра", "title": "Дроби: четыре действия", "idea": "Дробь показывает, сколько одинаковых частей взяли. Складывать удобно кусочки одного размера.", "steps": ["Для сложения и вычитания приведи дроби к общему знаменателю.", "При умножении перемножь числители и знаменатели; сократи общие множители.", "Для деления умножь первую дробь на обратную второй. Делитель должен быть ненулевым."], "example": ["1/2 + 1/3", "Общий знаменатель 6: 1/2 = 3/6, 1/3 = 2/6.", "3/6 + 2/6 = 5/6."], "error": "При сложении знаменатели не складывают: 1/2 + 1/2 = 1, а не 2/4.", "lab": "fraction", "qs": [{"q": "1/4 + 1/2 = ?", "a": "3/4", "why": "1/2 = 2/4, сумма 3/4."}, {"q": "2/3 · 3/4 = ?", "a": "1/2", "why": "6/12 сокращается до 1/2."}, {"q": "3/5 : 3 = ?", "a": "1/5", "why": "3/5 · 1/3 = 3/15 = 1/5."}]}, {"id": "divisibility", "group": "Алгебра", "title": "Делимость, простые множители, НОД и НОК", "idea": "Разложение числа на простые множители похоже на разбор конструкции на детали, которые дальше уже не разбираются.", "steps": ["На 2 делятся числа с чётной последней цифрой; на 5 — с последней цифрой 0 или 5; на 10 — с последней цифрой 0.", "На 3 делятся числа, сумма цифр которых делится на 3; для 9 правило такое же. Простое число имеет ровно два натуральных делителя: 1 и себя. Число 1 не простое.", "Для НОД возьми общие простые множители с меньшими показателями. Для НОК — все простые множители с большими показателями."], "example": ["Найти НОД и НОК чисел 12 и 18", "12=2²·3, 18=2·3².", "НОД=2·3=6; НОК=2²·3²=36."], "error": "НОД не больше меньшего числа, а НОК не меньше большего. Это удобная проверка.", "lab": "divisibility", "qs": [{"q": "НОД чисел 12 и 18?", "a": 6, "why": "Общие множители 2 и 3: 6."}, {"q": "НОК чисел 4 и 6?", "a": 12, "why": "Первое общее положительное кратное — 12."}, {"q": "Делится ли 123 на 3? 1 — да, 0 — нет.", "a": 1, "why": "1+2+3=6 делится на 3."}]}, {"id": "decimals", "group": "Алгебра", "title": "Десятичные и периодические дроби", "idea": "Десятичная запись — ещё один способ записать дробь. Иногда цифры после запятой повторяются бесконечно: 1/3 = 0,(3).", "steps": ["Чтобы перевести обычную дробь в десятичную, раздели числитель на знаменатель.", "Конечная десятичная дробь получается, если после сокращения в знаменателе есть только простые множители 2 и 5.", "Повторяющуюся группу цифр запиши в скобках: 0,272727… = 0,(27). Такая запись точная; 0,27 — приближение."], "example": ["3/8 в десятичной записи", "3 : 8 = 0,375.", "Проверка: 0,375 · 8 = 3."], "error": "0,(3) и 0,3 — разные числа. Не отбрасывай период при точном вычислении.", "lab": "fraction", "qs": [{"q": "Запиши 3/4 десятичной дробью.", "a": 0.75, "why": "3 : 4 = 0,75."}, {"q": "0,2 + 0,35 = ?", "a": 0.55, "why": "Сложи сотые: 20 + 35 = 55."}, {"q": "0,6 : 0,2 = ?", "a": 3, "why": "Умножь делимое и делитель на 10: 6 : 2 = 3."}]}, {"id": "rounding", "group": "Алгебра", "title": "Округление, прикидка и погрешность", "idea": "Округление заменяет число близким и более удобным. Прикидка помогает заметить неправдоподобный ответ.", "steps": ["Выбери разряд, который сохраняешь. Посмотри на следующую цифру.", "Если следующая цифра 0–4, оставь разряд; если 5–9 — увеличь его на единицу.", "Абсолютная погрешность — модуль разности точного и приближённого значений. Знак ≈ означает «примерно равно»."], "example": ["Округлить 7,846 до сотых", "Сохраняем 4 в разряде сотых. Следующая цифра 6, поэтому повышаем 4 до 5.", "7,846 ≈ 7,85. Погрешность: |7,846 − 7,85| = 0,004."], "error": "Не округляй много раз подряд: лучше один раз в конце расчёта.", "lab": "rounding", "qs": [{"q": "Округли 3,147 до сотых.", "a": 3.15, "why": "Следующая цифра 7, сотые увеличиваются."}, {"q": "Округли 28,4 до целых.", "a": 28, "why": "Десятые 4: округляем вниз."}, {"q": "Точное значение 12, приближённое 11,7. Погрешность?", "a": 0.3, "why": "|12 − 11,7| = 0,3."}]}, {"id": "percent", "group": "Алгебра", "title": "Проценты и изменения цены", "idea": "Один процент — одна сотая. Представь полоску из ста равных частей.", "steps": ["p% числа N — это N · p / 100.", "Если p% равны B, всё число равно B : (p/100).", "Увеличение на p%: умножь на 1 + p/100. Уменьшение: на 1 − p/100."], "example": ["Цена 800 ₽, скидка 15%", "Скидка: 800 · 0,15 = 120 ₽.", "Новая цена: 800 − 120 = 680 ₽."], "error": "Снижение и рост на один и тот же процент не отменяют друг друга: проценты берутся от разных чисел.", "lab": "percent", "qs": [{"q": "20% от 350 = ?", "a": 70, "why": "350 · 0,2 = 70."}, {"q": "25% числа равны 30. Какое это число?", "a": 120, "why": "30 : 0,25 = 120."}, {"q": "Цена 500 ₽ выросла на 10%. Новая цена?", "a": 550, "why": "500 · 1,1 = 550."}]}, {"id": "ratio", "group": "Алгебра", "title": "Отношения и пропорции", "idea": "Отношение сравнивает величины делением. Пропорция говорит: два отношения одинаковы.", "steps": ["В a/b = c/d произведения a·d и b·c равны; b и d ненулевые.", "При прямой пропорциональности увеличение одной величины в несколько раз увеличивает другую во столько же раз.", "При обратной пропорциональности произведение величин постоянно: чем больше скорость при фиксированном пути, тем меньше время."], "example": ["3 тетради стоят 90 ₽. Сколько стоят 5?", "Одна тетрадь: 90 : 3 = 30 ₽.", "Пять тетрадей: 30 · 5 = 150 ₽."], "error": "Прямая пропорциональность возможна при неизменной цене за штуку. Проверяй условие.", "lab": "proportion", "qs": [{"q": "x/3 = 8/6. Найди x.", "a": 4, "why": "6x = 24, x = 4."}, {"q": "4 кг стоят 280 ₽. Сколько стоят 3 кг?", "a": 210, "why": "280 : 4 · 3 = 210."}, {"q": "Путь 120 км. При скорости 60 км/ч сколько часов?", "a": 2, "why": "Время = путь : скорость = 2."}]}, {"id": "expressions", "group": "Алгебра", "title": "Буквенные выражения и подстановка", "idea": "Буква — место для числа. Формула работает как рецепт: подставь значение и выполни действия.", "steps": ["Сначала запиши значение каждой буквы. Отрицательные числа подставляй в скобках.", "Соблюдай порядок: скобки, степени, умножение и деление, затем сложение и вычитание.", "Выражение 1/(x−2) имеет смысл только при x ≠ 2: знаменатель не должен быть нулём."], "example": ["3x² − 2 при x = −2", "3 · (−2)² − 2 = 3 · 4 − 2.", "12 − 2 = 10."], "error": "−2² = −4, а (−2)² = 4. Скобки меняют основание степени.", "lab": "expression", "qs": [{"q": "2x + 3 при x = 4.", "a": 11, "why": "2 · 4 + 3 = 11."}, {"q": "x² при x = −3.", "a": 9, "why": "(−3) · (−3) = 9."}, {"q": "5(a − 1) при a = 3.", "a": 10, "why": "Сначала 3 − 1 = 2, затем 5 · 2 = 10."}]}, {"id": "identities", "group": "Алгебра", "title": "Тождества, скобки и подобные слагаемые", "idea": "Тождество верно при всех допустимых значениях букв. Подобные слагаемые — одинаковые буквенные «наборы».", "steps": ["3x + 2x = 5x: складываем коэффициенты одинаковой буквенной части.", "Плюс перед скобками сохраняет знаки. Минус перед скобками меняет знак каждого слагаемого.", "Распределительный закон: k(a+b) = ka+kb. Проверить пример подстановкой полезно, но одна подстановка не доказывает тождество."], "example": ["4x − (2x − 3) + x", "Раскрываем скобки: 4x − 2x + 3 + x.", "Собираем: (4 − 2 + 1)x + 3 = 3x + 3."], "error": "x и x² не подобные: их нельзя сложить в 2x².", "lab": "distribute", "qs": [{"q": "Коэффициент при x в 4x + 3x − 2x?", "a": 5, "why": "4 + 3 − 2 = 5."}, {"q": "Значение −(x − 5) при x = 2?", "a": 3, "why": "−x + 5 = −2 + 5 = 3."}, {"q": "Свободное число после раскрытия 3(x + 4)?", "a": 12, "why": "3x + 12."}]}, {"id": "powers", "group": "Алгебра", "title": "Степени и их свойства", "idea": "Степень — короткая запись произведения одинаковых множителей: 2³ = 2 · 2 · 2.", "steps": ["При умножении одинаковых оснований показатели складываются: aᵐ · aⁿ = aᵐ⁺ⁿ.", "При делении показатели вычитаются: aᵐ : aⁿ = aᵐ⁻ⁿ, a ≠ 0. Здесь рассматриваем m ≥ n. a⁰ = 1 для a ≠ 0.", "В степени степени показатели перемножаются: (aᵐ)ⁿ = aᵐⁿ. Для произведения (ab)ⁿ = aⁿbⁿ.", "Большие числа удобно записывать через степень 10: 3 000 000 = 3·10⁶. Здесь 10⁶ — единица с шестью нулями."], "example": ["x⁸ · x³ : x⁵", "Показатель: 8 + 3 − 5 = 6.", "Ответ x⁶, x ≠ 0. Основание не изменилось."], "error": "При a² · a³ показатели складывают, а при (a²)³ — перемножают.", "lab": "powers", "qs": [{"q": "2⁵ = ?", "a": 32, "why": "2 · 2 · 2 · 2 · 2 = 32."}, {"q": "Показатель в x⁷ : x³ : x³?", "a": 1, "why": "7 − 3 − 3 = 1."}, {"q": "(−2)³ = ?", "a": -8, "why": "4 · (−2) = −8."}]}, {"id": "monomials", "group": "Алгебра", "title": "Одночлены: коэффициент и степень", "idea": "Одночлен — произведение чисел и степеней переменных. Стандартный вид собирает числа и одинаковые буквы.", "steps": ["Перемножь числовые множители — получишь коэффициент.", "Степени одинаковых букв объедини. Разные буквы оставь отдельно.", "Степень ненулевого одночлена — сумма показателей переменных. У ненулевой константы степень 0."], "example": ["2x² · (−3xy)", "Числа: 2 · (−3) = −6. Буквы: x² · x = x³.", "Получилось −6x³y. Степень одночлена: 3 + 1 = 4."], "error": "Коэффициент не входит в степень одночлена. В −6x³y степень 4, а не −2.", "lab": "monomial", "qs": [{"q": "Коэффициент в 3x · (−2x²)?", "a": -6, "why": "3 · (−2) = −6."}, {"q": "Степень одночлена 7a²b³?", "a": 5, "why": "2 + 3 = 5."}, {"q": "Показатель x в (x²)³?", "a": 6, "why": "2 · 3 = 6."}]}, {"id": "polynomials", "group": "Алгебра", "title": "Многочлены: сложение и вычитание", "idea": "Многочлен — сумма одночленов. Удобно раскладывать слагаемые по «полочкам»: x² к x², x к x, числа к числам.", "steps": ["Раскрой скобки, внимательно следя за минусом.", "Приведи подобные слагаемые.", "Степень многочлена в стандартном виде — наибольшая степень его ненулевых одночленов."], "example": ["(2x² + 3x − 1) − (x² − x + 4)", "2x² + 3x − 1 − x² + x − 4.", "Ответ: x² + 4x − 5. Степень 2."], "error": "Минус перед второй скобкой относится ко всем её слагаемым.", "lab": "polynomial", "qs": [{"q": "Коэффициент x в (2x + 3) + (5x − 1)?", "a": 7, "why": "2 + 5 = 7."}, {"q": "Свободное число в (x + 4) − (x − 3)?", "a": 7, "why": "4 − (−3) = 7."}, {"q": "Степень 4x³ + 2x² − 7?", "a": 3, "why": "Наибольший показатель равен 3."}]}, {"id": "multiply", "group": "Алгебра", "title": "Умножение многочленов", "idea": "Каждое слагаемое первой скобки должно встретиться с каждым слагаемым второй.", "steps": ["Одночлен на многочлен: умножь одночлен на каждое слагаемое.", "Две скобки: выпиши все пары произведений. У двух двучленов получится четыре произведения.", "В конце собери подобные слагаемые."], "example": ["(x + 2)(x + 3)", "x·x + x·3 + 2·x + 2·3 = x² + 3x + 2x + 6.", "Ответ: x² + 5x + 6."], "error": "Нельзя умножить только первые и последние слагаемые: средние произведения тоже нужны.", "lab": "area", "qs": [{"q": "Коэффициент x в (x + 4)(x + 2)?", "a": 6, "why": "4x + 2x = 6x."}, {"q": "Свободное число в (x − 3)(x + 5)?", "a": -15, "why": "−3 · 5 = −15."}, {"q": "Коэффициент x² в 3x(2x + 1)?", "a": 6, "why": "3x · 2x = 6x²."}]}, {"id": "squares", "group": "Алгебра", "title": "Квадрат суммы и квадрат разности", "idea": "Большой квадрат можно разрезать на два квадрата и два одинаковых прямоугольника. Так видно, откуда берётся 2ab.", "steps": ["(a+b)² = a² + 2ab + b².", "(a−b)² = a² − 2ab + b². Последний квадрат положительный.", "Среднее слагаемое — удвоенное произведение, а не просто сумма чисел."], "example": ["(x + 3)²", "x² + 2·x·3 + 3².", "Ответ: x² + 6x + 9."], "error": "(a+b)² не равно a²+b²: потерялось 2ab.", "lab": "square", "qs": [{"q": "Коэффициент x в (x + 5)²?", "a": 10, "why": "2 · x · 5 = 10x."}, {"q": "Свободное число в (x − 4)²?", "a": 16, "why": "(−4)² = 16."}, {"q": "Вычисли 19².", "a": 361, "why": "(20−1)² = 400 − 40 + 1."}]}, {"id": "difference-squares", "group": "Алгебра", "title": "Разность квадратов", "idea": "Если две скобки отличаются только знаком, средние слагаемые взаимно уничтожаются.", "steps": ["(a−b)(a+b) = a²−b².", "Чтобы разложить разность квадратов, найди, какие выражения возводились в квадрат.", "Вынеси общий множитель сначала, если он есть."], "example": ["x² − 25", "25 = 5².", "x² − 5² = (x−5)(x+5)."], "error": "Сумма квадратов a²+b² по этому правилу не раскладывается.", "lab": "difference", "qs": [{"q": "Вычисли 21 · 19.", "a": 399, "why": "(20+1)(20−1) = 400−1."}, {"q": "Число b в x²−49 = (x−b)(x+b), b > 0?", "a": 7, "why": "49 = 7²."}, {"q": "Свободное число в (x−8)(x+8)?", "a": -64, "why": "−8² = −64."}]}, {"id": "factor", "group": "Алгебра", "title": "Общий множитель и группировка", "idea": "Разложить на множители — превратить сумму в произведение. Это раскрытие скобок в обратную сторону.", "steps": ["Найди множитель, который есть у каждого слагаемого.", "Раздели каждое слагаемое на него: результаты останутся в скобках.", "Для группировки объедини слагаемые так, чтобы после первого шага появились одинаковые скобки."], "example": ["ax + ay + bx + by", "a(x+y) + b(x+y).", "Вынеси (x+y): (a+b)(x+y). Проверка — раскрой скобки обратно."], "error": "После вынесения x из x² + x получаем x(x+1), а не x·x.", "lab": "factor", "qs": [{"q": "Число в скобках: 6x + 12 = 6(x + ?).", "a": 2, "why": "12 : 6 = 2."}, {"q": "Наибольший общий числовой множитель 12x и 18?", "a": 6, "why": "12 и 18 делятся на 6."}, {"q": "При x = 3 чему равно x(x + 1)?", "a": 12, "why": "3 · 4 = 12."}]}, {"id": "equations", "group": "Алгебра", "title": "Линейные уравнения", "idea": "Уравнение похоже на равновесие весов. Можно одинаково изменить обе чаши, и равенство сохранится.", "steps": ["Раскрой скобки и приведи подобные.", "Прибавь или вычти одно и то же выражение с обеих сторон. Это объясняет «перенос со сменой знака».", "В ax = b при a ≠ 0 раздели обе части на a. Если a = 0: при b = 0 решений бесконечно много, иначе решений нет."], "example": ["3x + 5 = 17", "Вычитаем 5: 3x = 12. Делим на 3: x = 4.", "Проверка: 3·4 + 5 = 17."], "error": "Нельзя делить на коэффициент, не проверив, не равен ли он нулю.", "lab": "equation", "qs": [{"q": "2x + 7 = 19. Найди x.", "a": 6, "why": "2x = 12, x = 6."}, {"q": "5(x−1) = 20. Найди x.", "a": 5, "why": "x−1 = 4, x = 5."}, {"q": "7−3x = 1. Найди x.", "a": 2, "why": "−3x = −6, x = 2."}]}, {"id": "word-problems", "group": "Алгебра", "title": "Задачи: цена, движение и работа", "idea": "Чтобы решить текстовую задачу, переведи историю в короткую математическую запись.", "steps": ["Назови неизвестное и его единицы. Запиши остальные величины через него.", "Используй связи: стоимость = цена·количество; путь = скорость·время; работа = производительность·время.", "Составь уравнение, реши и верни ответ в условия истории. Проверь, подходит ли число по смыслу."], "example": ["Три одинаковые тетради и ручка за 20 ₽ стоят 110 ₽", "Пусть x — цена тетради. 3x + 20 = 110.", "3x = 90, x = 30 ₽. Проверка: 90 + 20 = 110."], "error": "Минуты и часы нельзя подставлять вперемешку. Сначала приведи единицы.", "lab": "proportion", "qs": [{"q": "Скорость 60 км/ч, время 2,5 ч. Путь в км?", "a": 150, "why": "60 · 2,5 = 150."}, {"q": "4 тетради и ручка за 10 ₽ стоят 90 ₽. Цена тетради?", "a": 20, "why": "(90−10) : 4 = 20."}, {"q": "Мастер делает 6 деталей в час. Часов на 24 детали?", "a": 4, "why": "24 : 6 = 4."}]}, {"id": "coordinates", "group": "Алгебра", "title": "Координатная плоскость", "idea": "Координаты — адрес точки: сначала шаги вправо или влево, потом вверх или вниз.", "steps": ["Первая координата x относится к горизонтальной оси. Вторая y — к вертикальной.", "Положительные направления: вправо и вверх. Начало координат O имеет адрес (0;0).", "На оси x вторая координата равна 0. На оси y первая координата равна 0."], "example": ["Поставить точку A(−3;2)", "От начала идём на 3 единицы влево.", "Затем на 2 единицы вверх. Это вторая четверть."], "error": "Не меняй x и y местами: (2;3) и (3;2) — разные точки.", "lab": "coordinates", "qs": [{"q": "Абсцисса точки A(−4;7)?", "a": -4, "why": "Абсцисса — первая координата."}, {"q": "Ордината точки B(3;−2)?", "a": -2, "why": "Ордината — вторая координата."}, {"q": "Чему равна y у точки на оси x?", "a": 0, "why": "Точка не поднимается и не опускается от оси x."}]}, {"id": "functions", "group": "Алгебра", "title": "Функция, таблица и график", "idea": "Функция — правило, которое каждому допустимому входу x ставит в соответствие ровно один выход y.", "steps": ["Аргумент x выбираем, значение y вычисляем. Допустимые x образуют область определения.", "Функцию можно задать формулой, таблицей, графиком или словами.", "Точка графика имеет координаты (x;y). Читая график, сначала проверь названия осей и масштаб."], "example": ["y = 2x + 1 при x = −1, 0, 2", "Получаем y = −1, 1, 5.", "Точки (−1;−1), (0;1), (2;5) лежат на графике."], "error": "Один x не может давать два разных y у одной функции. Разные x могут давать одинаковый y.", "lab": "line", "qs": [{"q": "y = 3x−2. Найди y при x = 4.", "a": 10, "why": "3·4−2 = 10."}, {"q": "y = 2x+1. При каком x значение y = 7?", "a": 3, "why": "2x+1=7, x=3."}, {"q": "Функция y = 5. Чему равно y при x = −10?", "a": 5, "why": "Постоянная функция всегда даёт 5."}]}, {"id": "linear-function", "group": "Алгебра", "title": "Линейная функция и прямая пропорциональность", "idea": "График y = kx+b — прямая. Число b поднимает её, а k задаёт направление и крутизну.", "steps": ["Для построения достаточно двух разных точек. Найди y для двух значений x.", "Если k > 0, прямая идёт вверх слева направо; если k < 0 — вниз; если k = 0 — горизонтально.", "Прямая пропорциональность y = kx при k ≠ 0 проходит через начало координат. Параллельные разные прямые имеют одинаковые k и разные b."], "example": ["Построить y = 2x−1", "x=0 → y=−1. x=2 → y=3.", "Проведи прямую через (0;−1) и (2;3)."], "error": "b — значение y при x=0, а не координата пересечения с осью x.", "lab": "line", "qs": [{"q": "В y = −3x+4 чему равно k?", "a": -3, "why": "k — множитель при x."}, {"q": "В y = 2x−7 чему равно b?", "a": -7, "why": "Свободное число −7."}, {"q": "Для y = 4x найди y при x = 3.", "a": 12, "why": "4·3 = 12."}]}, {"id": "basic-graphs", "group": "Алгебра", "title": "Графики модуля, квадрата и куба", "idea": "Разные правила рисуют разные линии. Таблица из нескольких точек помогает увидеть форму, но не заменяет точную формулу.", "steps": ["График y=|x| похож на букву V. При x ≥ 0 имеем y=x, при x<0 имеем y=−x. Значения неотрицательны.", "График y=x² — парабола: числа x и −x дают одинаковый квадрат. График симметричен относительно оси y.", "Для y=x³ знак y совпадает со знаком x. График проходит через (−1;−1), (0;0), (1;1). Квадрат и куб в некоторых учебниках изучают позже; здесь это дополнительное знакомство."], "example": ["Сравним три функции при x=−2", "|−2|=2; (−2)²=4; (−2)³=−8.", "Один и тот же вход дал разные выходы, потому что правила разные."], "error": "В y=x² отрицательное x даёт положительное y. В y=x³ отрицательное x даёт отрицательное y.", "lab": "curves", "qs": [{"q": "y=|x| при x=−4. Найди y.", "a": 4, "why": "Модуль −4 равен 4."}, {"q": "y=x² при x=−3. Найди y.", "a": 9, "why": "(−3)²=9."}, {"q": "y=x³ при x=−2. Найди y.", "a": -8, "why": "(−2)³=−8."}]}, {"id": "two-variables", "group": "Алгебра", "title": "Линейное уравнение с двумя переменными", "idea": "В уравнении x+y=5 подходит много пар: например (1;4) и (2;3). На плоскости они образуют прямую.", "steps": ["Решение — пара чисел, которая превращает уравнение в верное равенство.", "В ax+by=c хотя бы один из коэффициентов a, b должен быть ненулевым. При b ≠ 0 вырази y.", "Если b=0 и a ≠ 0, получишь вертикальную прямую x=c/a."], "example": ["2x + y = 6", "Выразим y = 6−2x.", "При x=1 имеем y=4; при x=3 имеем y=0."], "error": "Не выбирай x и y независимо: их связывает уравнение.", "lab": "line", "qs": [{"q": "x+y=9. Если x=4, чему равно y?", "a": 5, "why": "9−4=5."}, {"q": "2x+y=7. Если x=2, чему равно y?", "a": 3, "why": "7−4=3."}, {"q": "3x+0y=12. Чему равно x?", "a": 4, "why": "3x=12; y может быть любым."}]}, {"id": "systems", "group": "Алгебра", "title": "Системы: подстановка, сложение и график", "idea": "Решение системы подходит сразу к двум уравнениям. На графике это общая точка двух прямых.", "steps": ["Подстановка: вырази одну переменную и подставь её во второе уравнение.", "Сложение: при необходимости умножь уравнения на ненулевые числа так, чтобы коэффициенты одной переменной стали противоположными; сложи.", "Пересечение прямых — одно решение, параллельные разные прямые — ни одного, совпадающие — бесконечно много."], "example": ["x+y=7 и x−y=1", "Сложим уравнения: 2x=8, x=4.", "Подставим: 4+y=7, y=3. Проверка: 4−3=1."], "error": "Найденный x — ещё не весь ответ: нужна пара (x;y) и проверка обоих уравнений.", "lab": "systems", "qs": [{"q": "x+y=10, x−y=2. Найди x.", "a": 6, "why": "Сложение даёт 2x=12."}, {"q": "В той же системе найди y.", "a": 4, "why": "10−6=4."}, {"q": "y=2x и y=x+3. Найди x пересечения.", "a": 3, "why": "2x=x+3, x=3."}]}, {"id": "system-problems", "group": "Алгебра", "title": "Текстовые задачи с системой", "idea": "Две неизвестные величины удобно назвать двумя буквами. Два независимых условия превращаются в два уравнения.", "steps": ["Укажи, что означают x и y, и запиши единицы.", "Переведи каждое условие в отдельное равенство. Сумма предметов и общая стоимость — разные условия.", "Реши систему и проверь ответ в исходной истории. Количество предметов должно быть целым и неотрицательным."], "example": ["Купили 5 тетрадей: по 20 ₽ и по 30 ₽. Всего 120 ₽. Сколько каждого вида?", "x+y=5, 20x+30y=120. Из первого x=5−y. Подставим: 100−20y+30y=120.", "10y=20, y=2, x=3. Проверка: 3·20+2·30=120 ₽."], "error": "Нельзя складывать количество тетрадей и рубли в одной сумме: у каждой строки системы должен быть смысл.", "lab": "systems", "qs": [{"q": "В разобранной задаче сколько тетрадей по 20 ₽?", "a": 3, "why": "x=5−2=3."}, {"q": "Всего 12 животных: куры и кролики. Всего 32 ноги. Сколько кроликов?", "a": 4, "why": "x+y=12, 2x+4y=32. Вычти 2(x+y)=24: 2y=8."}, {"q": "Два числа в сумме дают 20, их разность 4. Большее?", "a": 12, "why": "Сложение уравнений даёт 2x=24."}]}, {"id": "segments", "group": "Геометрия", "title": "Точка, прямая, отрезок и ломаная", "idea": "Точка — положение. Прямая бесконечна в обе стороны, луч — в одну, отрезок ограничен двумя концами.", "steps": ["Через две различные точки проходит ровно одна прямая.", "Если B лежит между A и C, то AC=AB+BC. Середина делит отрезок на равные части.", "Длина ломаной — сумма звеньев. Замкнутая ломаная без самопересечений образует границу многоугольника; её длина — периметр."], "example": ["B между A и C, AB=4 см, BC=7 см", "Складываем соседние отрезки.", "AC=4+7=11 см."], "error": "Рисунок может быть не в масштабе. Используй данные, а не длины на экране.", "lab": "segment", "qs": [{"q": "B между A и C. AC=15, AB=6. Найди BC.", "a": 9, "why": "15−6=9."}, {"q": "Отрезок 18 см разделён пополам. Длина половины?", "a": 9, "why": "18:2=9."}, {"q": "Ломаная имеет звенья 3, 5 и 4 см. Длина?", "a": 12, "why": "3+5+4=12."}]}, {"id": "angles", "group": "Геометрия", "title": "Углы и биссектриса", "idea": "Угол образуют два луча с общим началом. Его величина показывает поворот от одного луча к другому.", "steps": ["Острый угол меньше 90°, прямой равен 90°, тупой больше 90°, но меньше 180°. Развёрнутый равен 180°.", "Биссектриса делит угол на два равных угла.", "При измерении транспортиром совмести центр с вершиной, а ноль шкалы — с одной стороной."], "example": ["Биссектриса угла 74°", "Делим угол поровну: 74:2.", "Каждая часть равна 37°."], "error": "Не выбирай внешнюю шкалу транспортира автоматически: отсчёт должен начинаться от нуля на стороне угла.", "lab": "angle", "qs": [{"q": "Половина угла 86°?", "a": 43, "why": "86:2=43."}, {"q": "Какова величина прямого угла?", "a": 90, "why": "Это четверть полного оборота."}, {"q": "Две части угла равны 20° и 35°. Весь угол?", "a": 55, "why": "20+35=55."}]}, {"id": "adjacent", "group": "Геометрия", "title": "Смежные и вертикальные углы", "idea": "Пересекающиеся прямые образуют четыре угла. Соседние могут составлять развёрнутый угол, противоположные равны.", "steps": ["Смежные углы имеют общую сторону, а две другие — противоположные лучи. Их сумма 180°.", "Вертикальные углы образованы двумя пересекающимися прямыми и лежат напротив; они равны.", "Обоснование: оба вертикальных угла дополняют один и тот же соседний угол до 180°."], "example": ["Один из углов пересечения равен 65°", "Вертикальный ему равен 65°.", "Смежный равен 180−65=115°."], "error": "Не любые соседние углы смежные: две внешние стороны должны составлять прямую.", "lab": "adjacent", "qs": [{"q": "Угол 48°. Найди смежный.", "a": 132, "why": "180−48=132."}, {"q": "Угол 117°. Найди вертикальный.", "a": 117, "why": "Вертикальные углы равны."}, {"q": "Смежные углы равны. Величина каждого?", "a": 90, "why": "180:2=90."}]}, {"id": "perpendicular", "group": "Геометрия", "title": "Перпендикуляр, наклонная и расстояние", "idea": "Кратчайший путь от точки до прямой идёт под прямым углом. Он называется перпендикуляром.", "steps": ["Перпендикулярные прямые пересекаются под углом 90°.", "Расстояние от точки до прямой — длина перпендикуляра, опущенного на неё.", "Любая наклонная из той же точки к этой прямой длиннее перпендикуляра. Среди наклонных большей проекции соответствует большая длина."], "example": ["Из P к прямой проведены перпендикуляр 4 см и наклонная 6 см", "Расстояние измеряется по перпендикуляру.", "Ответ: 4 см."], "error": "Не выбирай удобный наклонный отрезок для измерения расстояния до прямой.", "lab": "perpendicular", "qs": [{"q": "Угол между перпендикулярными прямыми?", "a": 90, "why": "По определению."}, {"q": "Перпендикуляр 5 см, наклонная 8 см. Расстояние до прямой?", "a": 5, "why": "Берём длину перпендикуляра."}, {"q": "Перпендикулярные прямые образуют сколько прямых углов?", "a": 4, "why": "Вокруг точки пересечения четыре угла по 90°."}]}, {"id": "symmetry", "group": "Геометрия", "title": "Осевая симметрия", "idea": "Ось симметрии работает как зеркало. Точка и её отражение находятся на одинаковом расстоянии по разные стороны оси.", "steps": ["Отрезок между точкой и отражением перпендикулярен оси и делится ею пополам.", "При отражении сохраняются длины и углы. Точки на оси остаются на месте.", "Отражение относительно оси y меняет знак x: (x;y) → (−x;y). Относительно оси x меняется знак y."], "example": ["Отразить A(3;2) относительно оси y", "Горизонтальное положение меняет знак, высота остаётся.", "A′(−3;2)."], "error": "При отражении в одной оси меняется одна координата, а не обе.", "lab": "symmetry", "qs": [{"q": "У A(4;3) отражение в оси y. Найди новую x.", "a": -4, "why": "x меняет знак."}, {"q": "У A(4;3) отражение в оси x. Найди новую y.", "a": -3, "why": "y меняет знак."}, {"q": "Точка в 5 см от оси. Расстояние до её отражения?", "a": 10, "why": "5+5=10."}]}, {"id": "triangle-lines", "group": "Геометрия", "title": "Треугольник: высота, медиана, биссектриса", "idea": "У треугольника три вершины и три стороны. Из вершины можно провести три разных «особых маршрута».", "steps": ["Медиана идёт к середине противоположной стороны.", "Биссектриса делит угол вершины пополам. Высота перпендикулярна прямой, содержащей противоположную сторону.", "У тупоугольного треугольника некоторые высоты лежат вне треугольника. Эти три линии обычно не совпадают."], "example": ["Медиана AM делит сторону BC=12 см", "По определению M — середина BC.", "BM=MC=6 см. Никакого условия о прямом угле нет."], "error": "Медиана не обязана быть перпендикулярна стороне. Не путай определения.", "lab": "triangle-lines", "qs": [{"q": "Медиана делит сторону 14 см. Длина каждой части?", "a": 7, "why": "14:2=7."}, {"q": "Биссектриса делит угол 50°. Каждая часть?", "a": 25, "why": "50:2=25."}, {"q": "Угол между высотой и прямой противоположной стороны?", "a": 90, "why": "Высота — перпендикуляр."}]}, {"id": "isosceles", "group": "Геометрия", "title": "Равнобедренный и равносторонний треугольники", "idea": "У равнобедренного треугольника две равные стороны. Его вершина будто стоит над серединой основания.", "steps": ["Углы при основании равны. Обратно: если два угла равны, то равны и противолежащие стороны.", "Медиана к основанию также является высотой и биссектрисой. Это можно доказать равенством двух получившихся треугольников по трём сторонам.", "У равностороннего треугольника все стороны равны и каждый угол равен 60°."], "example": ["Угол при вершине равнобедренного треугольника 40°", "На два равных угла остаётся 180−40=140°.", "Каждый угол при основании равен 140:2=70°."], "error": "Равны углы при основании, а не обязательно все три угла.", "lab": "isosceles", "qs": [{"q": "Угол при вершине 80°. Угол при основании?", "a": 50, "why": "(180−80):2=50."}, {"q": "Все стороны треугольника равны. Каждый угол?", "a": 60, "why": "180:3=60."}, {"q": "Боковые стороны по 5, основание 6. Периметр?", "a": 16, "why": "5+5+6=16."}]}, {"id": "congruence", "group": "Геометрия", "title": "Три признака равенства треугольников", "idea": "Равные треугольники можно совместить наложением. Достаточно проверить один из трёх наборов условий.", "steps": ["Первый признак: две стороны и угол между ними.", "Второй: сторона и два прилежащих к ней угла. Третий: три стороны.", "Сопоставь вершины правильно. Из равенства треугольников следуют равенства соответствующих сторон и углов. Три равных угла не гарантируют равенство размеров."], "example": ["AB=DE, AC=DF, ∠A=∠D", "Угол A лежит между AB и AC, угол D — между DE и DF.", "Значит, △ABC = △DEF по первому признаку. Поэтому BC=EF."], "error": "Две стороны и произвольный угол — недостаточно: для первого признака нужен угол между сторонами.", "lab": "congruence", "qs": [{"q": "Сколько сторон сравнивают в третьем признаке?", "a": 3, "why": "Все три пары соответствующих сторон."}, {"q": "△ABC=△DEF, BC=8. Найди EF.", "a": 8, "why": "Соответствующие стороны равных треугольников равны."}, {"q": "△ABC=△DEF, ∠B=52°. Найди ∠E.", "a": 52, "why": "B соответствует E."}]}, {"id": "parallel", "group": "Геометрия", "title": "Параллельные прямые и секущая", "idea": "Параллельные прямые в одной плоскости не пересекаются. Секущая помогает распознавать их по углам.", "steps": ["Если накрест лежащие углы равны, прямые параллельны. Если прямые параллельны, эти углы равны.", "Соответственные углы при параллельных прямых равны. Односторонние внутренние в сумме дают 180°.", "Через точку вне прямой проходит ровно одна прямая, параллельная данной."], "example": ["Односторонний внутренний угол 110°, прямые параллельны", "Их сумма 180°.", "Второй угол: 180−110=70°."], "error": "Сначала определи положение углов относительно прямых и секущей. Не все углы на рисунке равны.", "lab": "parallel", "qs": [{"q": "Накрест лежащий к углу 62° при параллельных прямых?", "a": 62, "why": "Накрест лежащие углы равны."}, {"q": "Односторонний внутренний к 125°?", "a": 55, "why": "180−125=55."}, {"q": "Соответственный к углу 93°?", "a": 93, "why": "Соответственные углы равны."}]}, {"id": "triangle-angles", "group": "Геометрия", "title": "Сумма углов и внешний угол", "idea": "Три угла любого треугольника вместе дают развёрнутый угол — 180°.", "steps": ["Чтобы найти третий угол, вычти два известных из 180°.", "Для доказательства проведи через вершину прямую, параллельную противоположной стороне: два угла переносятся как накрест лежащие и вместе с третьим составляют 180°.", "Внешний угол равен сумме двух внутренних углов, не смежных с ним. Он дополняет смежный внутренний до 180°."], "example": ["В треугольнике углы 45° и 65°", "Третий: 180−45−65=70°.", "Внешний при этой вершине: 180−70=110° = 45°+65°."], "error": "Внешний угол — не сумма всех трёх внутренних.", "lab": "triangle", "qs": [{"q": "Два угла 50° и 60°. Третий?", "a": 70, "why": "180−50−60=70."}, {"q": "Внешний угол при внутреннем 75°?", "a": 105, "why": "180−75=105."}, {"q": "Удалённые внутренние углы 40° и 55°. Внешний?", "a": 95, "why": "40+55=95."}]}, {"id": "triangle-inequality", "group": "Геометрия", "title": "Стороны и углы: неравенства", "idea": "Три палочки не всегда замкнутся в треугольник: две короткие должны вместе перекрывать самую длинную.", "steps": ["Любая сторона меньше суммы двух других. Для положительных длин достаточно проверить наибольшую.", "Напротив большей стороны лежит больший угол, и наоборот. Напротив равных сторон — равные углы.", "Если известны a и b, третья сторона c удовлетворяет |a−b| < c < a+b. Путь по ломаной не короче прямого отрезка между концами."], "example": ["Две стороны 4 и 7 см", "Третья больше 7−4=3 и меньше 7+4=11.", "Например, 5 см подходит, а 3 см — нет: треугольник вырождается."], "error": "Равенство в неравенстве треугольника не подходит: вершины окажутся на одной прямой.", "lab": "triangle-inequality", "qs": [{"q": "Стороны 3, 4, 8. Треугольник существует? 1 — да, 0 — нет.", "a": 0, "why": "3+4=7 < 8."}, {"q": "Стороны 4 и 7. Наименьшая целая третья сторона?", "a": 4, "why": "Нужна целая длина строго больше 3."}, {"q": "Углы 40°, 60°, 80°. Напротив наибольшей стороны угол?", "a": 80, "why": "Большая сторона лежит напротив большего угла."}]}, {"id": "right-triangle", "group": "Геометрия", "title": "Прямоугольный треугольник", "idea": "Две стороны прямого угла — катеты. Напротив прямого угла лежит самая длинная сторона — гипотенуза.", "steps": ["Два острых угла в сумме дают 90°.", "Катет напротив угла 30° равен половине гипотенузы. Обратно: если катет равен половине гипотенузы, напротив него 30°.", "Медиана к гипотенузе равна её половине. Прямоугольные треугольники равны по двум катетам; по гипотенузе и катету; по катету и соответствующему острому углу; по гипотенузе и острому углу."], "example": ["Гипотенуза 14 см, один угол 30°", "Катет напротив 30°: 14:2=7 см.", "Медиана к гипотенузе также 7 см. Второй острый угол 60°."], "error": "Половине гипотенузы равен именно катет напротив 30°, а не любой катет.", "lab": "right", "qs": [{"q": "Острый угол 35°. Другой острый угол?", "a": 55, "why": "90−35=55."}, {"q": "Гипотенуза 18. Катет напротив 30°?", "a": 9, "why": "18:2=9."}, {"q": "Гипотенуза 10. Медиана к ней?", "a": 5, "why": "Половина гипотенузы."}]}, {"id": "proof", "group": "Геометрия", "title": "Как читать и строить доказательство", "idea": "Доказательство — цепочка причин. «На рисунке похоже» недостаточно: каждый шаг опирается на условие, определение или теорему.", "steps": ["Выпиши «дано» и «доказать». Отметь равные элементы на чертеже.", "Найди мостик: признак равенства, свойство параллельных прямых или другое известное правило.", "Различай свойство и признак. Свойство: из равнобедренности следуют равные углы. Признак: из равенства углов следует равнобедренность. Чтобы опровергнуть «всегда», достаточно одного контрпримера."], "example": ["Дано AB=AC. Медиана AM. Доказать ∠BAM=∠MAC", "BM=MC по определению медианы; AM — общая; AB=AC по условию.", "△ABM=△ACM по трём сторонам. Соответствующие углы при A равны."], "error": "Не используй утверждение, которое только собираешься доказать, как готовое основание.", "lab": "proof", "qs": [{"q": "Сколько пар равных сторон найдено в разобранном доказательстве?", "a": 3, "why": "AB=AC, BM=MC, AM=AM."}, {"q": "Сколько контрпримеров достаточно, чтобы опровергнуть «всегда»?", "a": 1, "why": "Одно исключение опровергает универсальное утверждение."}, {"q": "∠BAM=28°, AM — биссектриса. Найди ∠BAC.", "a": 56, "why": "28+28=56."}]}, {"id": "locus", "group": "Геометрия", "title": "Геометрические места точек", "idea": "Геометрическое место — все точки, удовлетворяющие одному условию. Например, точки на одном расстоянии от центра образуют окружность.", "steps": ["Серединный перпендикуляр к отрезку состоит из точек, равноудалённых от его концов. Обратное утверждение тоже верно.", "Биссектриса угла состоит из внутренних точек угла, равноудалённых от его сторон. Расстояния измеряются по перпендикулярам.", "Свойство серединного перпендикуляра следует из равенства прямоугольных треугольников по двум катетам."], "example": ["P на серединном перпендикуляре к AB, PA=8 см", "P равноудалена от A и B.", "PB=8 см."], "error": "Равноудалённость от сторон угла означает равные перпендикуляры, а не произвольные отрезки.", "lab": "locus", "qs": [{"q": "PA=6, P на серединном перпендикуляре AB. PB?", "a": 6, "why": "PA=PB."}, {"q": "Точка на биссектрисе в 3 см от одной стороны. От другой?", "a": 3, "why": "Расстояния до сторон равны."}, {"q": "Окружность радиуса 7. Расстояние центра до любой её точки?", "a": 7, "why": "Это определение окружности."}]}, {"id": "circle", "group": "Геометрия", "title": "Окружность, круг, хорда и диаметр", "idea": "Окружность — граница, круг — граница вместе с внутренней областью. Все точки окружности одинаково удалены от центра.", "steps": ["Радиус соединяет центр с окружностью. Диаметр проходит через центр и равен двум радиусам.", "Хорда соединяет две точки окружности. Диаметр — наибольшая хорда.", "Перпендикуляр из центра к хорде делит её пополам. Равные хорды одной окружности равноудалены от центра."], "example": ["Радиус 5 см. Перпендикуляр из центра делит хорду длиной 8 см", "Диаметр 2·5=10 см.", "Половина хорды 8:2=4 см."], "error": "Не всякая хорда — диаметр: она должна проходить через центр.", "lab": "circle", "qs": [{"q": "Радиус 6. Диаметр?", "a": 12, "why": "2·6=12."}, {"q": "Диаметр 15. Радиус?", "a": 7.5, "why": "15:2=7,5."}, {"q": "Хорда 10 разделена перпендикуляром из центра. Половина?", "a": 5, "why": "10:2=5."}]}, {"id": "tangent", "group": "Геометрия", "title": "Окружность и прямая: касательная", "idea": "Прямая может пройти мимо окружности, коснуться её или пересечь в двух точках.", "steps": ["Сравни расстояние d от центра до прямой с радиусом R: d>R — общих точек нет, d=R — одна, d<R — две.", "Касательная имеет одну общую точку с окружностью. Радиус к точке касания перпендикулярен касательной.", "Отрезки двух касательных из одной внешней точки равны: это следует из равенства прямоугольных треугольников по гипотенузе и катету."], "example": ["R=4 см, d=4 см", "Расстояние равно радиусу.", "Прямая касается окружности; угол с радиусом 90°."], "error": "Расстояние до прямой всегда измеряется по перпендикуляру.", "lab": "tangent", "qs": [{"q": "R=5, d=3. Сколько общих точек?", "a": 2, "why": "d<R: секущая."}, {"q": "Угол радиуса и касательной в точке касания?", "a": 90, "why": "Радиус перпендикулярен касательной."}, {"q": "Один отрезок касательной из P равен 7. Другой?", "a": 7, "why": "Отрезки касательных из одной точки равны."}]}, {"id": "incircle", "group": "Геометрия", "title": "Вписанная и описанная окружности", "idea": "Вписанная окружность касается сторон, описанная проходит через вершины. Это два разных способа окружить треугольник кругом.", "steps": ["Центр вписанной окружности — пересечение биссектрис: точка равноудалена от сторон. Радиусы к точкам касания перпендикулярны сторонам.", "Центр описанной окружности — пересечение серединных перпендикуляров: точка равноудалена от вершин. Он может лежать и вне треугольника.", "Центр окружности, вписанной в угол, лежит на его биссектрисе. У прямоугольного треугольника центр описанной окружности — середина гипотенузы."], "example": ["Гипотенуза прямоугольного треугольника 12 см", "Центр описанной окружности — середина гипотенузы.", "Радиус равен 12:2=6 см."], "error": "Биссектрисы находят центр вписанной окружности, а серединные перпендикуляры — описанной.", "lab": "incircle", "qs": [{"q": "Гипотенуза 16. Радиус описанной окружности?", "a": 8, "why": "Половина гипотенузы."}, {"q": "Центр вписанной окружности в 4 см от одной стороны. От другой?", "a": 4, "why": "Это тот же радиус."}, {"q": "Сколько сторон треугольника касается вписанная окружность?", "a": 3, "why": "Всех трёх сторон."}]}, {"id": "construction", "group": "Геометрия", "title": "Построения циркулем и линейкой", "idea": "Циркуль переносит расстояние, линейка проводит прямую. В классических построениях деления линейки не используют.", "steps": ["Серединный перпендикуляр: из обоих концов отрезка проведи дуги одного радиуса, большего половины отрезка; соедини две точки пересечения.", "Биссектриса: дуга из вершины пересекает стороны; из полученных точек проведи равные дуги внутри угла. Соедини вершину с их пересечением.", "Треугольник по трём сторонам: построй основание; из его концов проведи окружности радиусов двух других сторон; их пересечение — третья вершина. Перенос угла выполняют переносом дуги и хорды между её пересечениями со сторонами."], "example": ["Построить треугольник со сторонами 4, 5, 6 см", "Построй основание 6 см. Из его концов проведи окружности радиусов 4 и 5 см.", "Соедини их точку пересечения с концами основания. Есть два зеркальных положения."], "error": "Перед построением по трём сторонам проверь неравенство треугольника.", "lab": "construction", "qs": [{"q": "Отрезок 8 см. Минимальный целый радиус дуг для серединного перпендикуляра?", "a": 5, "why": "Радиус должен быть строго больше 4."}, {"q": "Биссектриса угла 60°. Половина?", "a": 30, "why": "60:2=30."}, {"q": "Можно построить невырожденный треугольник 2, 3, 5? 1 — да, 0 — нет.", "a": 0, "why": "2+3=5: вершины лежат на одной прямой."}]}, {"id": "tables", "group": "Вероятность и статистика", "title": "Таблицы и сбор данных", "idea": "Таблица помогает не потерять, что именно измерили. В одной строке — одно наблюдение или объект.", "steps": ["Подпиши столбцы и единицы измерения. Пропущенное значение не равно нулю.", "Проверяй, что сравниваешь одно и то же: цены за одинаковую массу, время в одинаковых единицах.", "Итог — сумма значений; доля группы — её число, делённое на общее. Вывод относится к собранным данным, а не автоматически ко всем людям."], "example": ["За три дня прочитано 10, 15 и 5 страниц", "Всего: 10+15+5=30 страниц.", "Во второй день: 15/30=1/2, то есть 50% всех страниц."], "error": "Не складывай величины с разными единицами в один бессмысленный итог.", "lab": "bars", "qs": [{"q": "Продано 4, 7 и 9 книг за три дня. Всего?", "a": 20, "why": "4+7+9=20."}, {"q": "В таблице 8 мальчиков и 12 девочек. Всего детей?", "a": 20, "why": "8+12=20."}, {"q": "Доля девочек из 20 детей, если их 12? В процентах.", "a": 60, "why": "12/20·100=60."}]}, {"id": "charts", "group": "Вероятность и статистика", "title": "Столбчатые и круговые диаграммы", "idea": "Столбики сравнивают количества, круг показывает части одного целого.", "steps": ["У столбчатой диаграммы проверь ось и масштаб. Для честного сравнения высот столбиков обычно начинают шкалу с нуля.", "Для круговой диаграммы сумма долей — 100%, а сумма углов секторов — 360°.", "Угол сектора = доля · 360°. Подписи нужны: цвета без легенды ничего не объясняют."], "example": ["Из 20 детей 5 выбрали футбол", "Доля: 5/20=1/4=25%.", "Угол сектора: 360·1/4=90°."], "error": "Круговая диаграмма подходит для частей одного целого. Проценты из разных групп нельзя просто объединить в круг.", "lab": "charts", "qs": [{"q": "Сектор для 50% имеет угол?", "a": 180, "why": "360·0,5=180."}, {"q": "Сектор 90°. Сколько это процентов?", "a": 25, "why": "90/360·100=25."}, {"q": "Высоты столбиков 8 и 13. Разница?", "a": 5, "why": "13−8=5."}]}, {"id": "real-graphs", "group": "Вероятность и статистика", "title": "Графики реальных процессов", "idea": "График рассказывает историю изменения. Сначала прочитай, что откладывается по каждой оси.", "steps": ["Выбери значение на горизонтальной оси, дойди до графика и прочитай значение по вертикальной.", "Горизонтальный участок означает, что показанная величина не меняется. Для графика пути это остановка.", "По двум точкам найди изменение: новое минус старое. Средняя скорость на участке — изменение пути, делённое на время."], "example": ["На графике пути: в 1 ч — 3 км, в 3 ч — 7 км", "За 2 часа путь увеличился на 4 км.", "Средняя скорость: 4:2=2 км/ч."], "error": "График скорости и график пути читаются по-разному. Смотри подписи осей.", "lab": "journey", "qs": [{"q": "В 0 ч путь 0 км, в 2 ч — 10 км. Средняя скорость?", "a": 5, "why": "10:2=5."}, {"q": "Температура выросла с −3 до 4 °C. На сколько градусов?", "a": 7, "why": "4−(−3)=7."}, {"q": "Путь с 2 до 5 ч не менялся. Сколько часов стояли?", "a": 3, "why": "5−2=3."}]}, {"id": "mean", "group": "Вероятность и статистика", "title": "Среднее арифметическое", "idea": "Среднее — сколько досталось бы каждому, если всё сложить и поделить поровну.", "steps": ["Сложи все значения, включая повторяющиеся.", "Раздели сумму на количество значений.", "Среднее чувствительно к очень большим и очень маленьким наблюдениям. Оно не обязано совпадать с одним из значений."], "example": ["Результаты: 2, 3, 4, 7", "Сумма 16, наблюдений 4.", "Среднее 16:4=4."], "error": "Делить нужно на число наблюдений, а не на число разных значений.", "lab": "stats", "qs": [{"q": "Среднее чисел 2, 4, 6?", "a": 4, "why": "(2+4+6):3=4."}, {"q": "Среднее 5 и 8?", "a": 6.5, "why": "13:2=6,5."}, {"q": "Среднее четырёх чисел равно 7. Их сумма?", "a": 28, "why": "7·4=28."}]}, {"id": "median", "group": "Вероятность и статистика", "title": "Медиана, минимум, максимум и размах", "idea": "Медиана — середина упорядоченного ряда. Размах показывает расстояние от самого маленького значения до самого большого.", "steps": ["Сначала расположи числа по возрастанию.", "При нечётном количестве медиана — центральное число; при чётном — среднее двух центральных.", "Размах = максимум − минимум. Не путай медиану со средним арифметическим."], "example": ["Данные: 9, 2, 3, 20, 4", "Упорядочим: 2, 3, 4, 9, 20. Медиана 4.", "Размах 20−2=18. Среднее при этом 38:5=7,6."], "error": "Без упорядочивания нельзя брать «число в середине записи».", "lab": "stats", "qs": [{"q": "Медиана чисел 8, 1, 3?", "a": 3, "why": "Ряд 1,3,8: в центре 3."}, {"q": "Медиана 1, 3, 5, 9?", "a": 4, "why": "Среднее 3 и 5 равно 4."}, {"q": "Размах чисел −2, 4, 7?", "a": 9, "why": "7−(−2)=9."}]}, {"id": "random", "group": "Вероятность и статистика", "title": "Случайные события и вероятность", "idea": "Случайное событие может произойти, а может не произойти. Вероятность описывает шанс, а не обещает исход отдельной попытки.", "steps": ["Достоверное событие обязательно произойдёт, невозможное не произойдёт. Их вероятности 1 и 0.", "Для конечного набора равновозможных исходов вероятность = число подходящих исходов / число всех исходов.", "Для честного кубика шесть равновозможных граней. В реальном опыте равновозможность нужно обосновать. Маловероятное событие всё же возможно."], "example": ["Шанс получить чётное число на честном кубике", "Подходят 2, 4, 6: три исхода из шести.", "Вероятность 3/6=1/2=0,5."], "error": "Вероятность 1/2 не значит, что в каждых двух бросках обязательно будет один успех.", "lab": "probability", "qs": [{"q": "Вероятность орла у честной монеты?", "a": "1/2", "why": "Два равновозможных исхода."}, {"q": "Вероятность семёрки на обычном кубике?", "a": 0, "why": "На гранях числа от 1 до 6."}, {"q": "Вероятность числа больше 4 на честном кубике?", "a": "1/3", "why": "Подходят 5 и 6: 2/6=1/3."}]}, {"id": "frequency", "group": "Вероятность и статистика", "title": "Частота, изменчивость и устойчивость", "idea": "Частота — доля успехов в проведённом опыте. Она вычисляется по данным, а вероятность описывает модель.", "steps": ["Относительная частота = число успехов / число испытаний.", "Повторные измерения и опыты дают разные результаты: это изменчивость. На неё могут влиять условия и случайность.", "В длинных сериях независимых одинаковых испытаний частота обычно приближается к вероятности. Это не обязано происходить с каждым новым броском."], "example": ["Из 50 бросков монеты 28 орлов", "Частота 28/50=0,56=56%.", "Это не доказательство нечестности монеты: в короткой серии возможны отклонения."], "error": "Не подменяй вероятность частотой единственной короткой серии и не обещай точный баланс.", "lab": "frequency", "qs": [{"q": "Из 40 попыток 10 успехов. Частота?", "a": "1/4", "why": "10/40=1/4."}, {"q": "Из 100 бросков 53 орла. Частота в процентах?", "a": 53, "why": "53/100·100=53%."}, {"q": "Частота 0,3 в 20 попытках. Сколько успехов?", "a": 6, "why": "0,3·20=6."}]}, {"id": "graphs", "group": "Вероятность и статистика", "title": "Графы: вершины, рёбра, пути и циклы", "idea": "Граф — схема связей. Города можно обозначить точками, дороги — линиями. Длина линии на схеме не обязана отражать расстояние.", "steps": ["Вершина — объект, ребро — связь. Степень вершины — число концов рёбер, приходящих в неё; петля считается дважды.", "Сумма степеней всех вершин равна удвоенному числу рёбер: каждое ребро учитывается у двух концов.", "Путь соединяет вершины по рёбрам. Цикл возвращается к началу. Граф связный, если любые две вершины можно соединить путём."], "example": ["Три вершины соединены треугольником", "У каждой вершины степень 2. Сумма 6.", "Рёбер 6:2=3. Можно пройти цикл A→B→C→A."], "error": "Геометрическое пересечение нарисованных рёбер не становится вершиной, если она специально не обозначена.", "lab": "graph", "qs": [{"q": "Сумма степеней вершин 10. Сколько рёбер?", "a": 5, "why": "Каждое ребро посчитали два раза."}, {"q": "В треугольном графе степень каждой вершины?", "a": 2, "why": "К каждой вершине подходят два ребра."}, {"q": "Цепочка A—B—C—D. Сколько рёбер?", "a": 3, "why": "AB, BC, CD."}]}, {"id": "euler", "group": "Вероятность и статистика", "title": "Обход графа и направления", "idea": "Можно ли пройти каждую дорогу ровно один раз? Это задача об эйлеровом пути.", "steps": ["В связном неориентированном графе эйлеров путь существует, если нечётных вершин 0 или 2. Вершины без рёбер при этом не учитываем.", "Если нечётных вершин 2, путь начинается в одной и заканчивается в другой. Если 0 — возможен замкнутый обход.", "В ориентированном графе рёбра имеют стрелки: двигаться можно только по направлению. Простое правило про нечётные степени к нему не применяют."], "example": ["Цепочка A—B—C—D", "Степени: 1, 2, 2, 1. Две нечётные вершины.", "Обход всех рёбер: A→B→C→D. Начало и конец — нечётные вершины."], "error": "Эйлеров путь проходит каждое ребро один раз, но может посещать вершину несколько раз.", "lab": "euler", "qs": [{"q": "У цепочки A—B—C—D сколько нечётных вершин?", "a": 2, "why": "A и D имеют степень 1."}, {"q": "У треугольного графа сколько нечётных вершин?", "a": 0, "why": "Все степени равны 2."}, {"q": "В связном графе четыре нечётные вершины. Есть эйлеров путь? 1 — да, 0 — нет.", "a": 0, "why": "Для такого пути нужны 0 или 2 нечётные вершины."}]}];